//! 🛂️ Actual original History validators retain only paid indexes and complete caller causes.
use super::*;
use semio_framework_os_store_text_io::ArtifactSqliteSnapshotHost;
use std::sync::atomic::{AtomicBool,Ordering};
fn contract()->serde_json::Value{f()["directionalValidation"].clone()}
fn edit(database:&mut SqliteDatabase,case:&serde_json::Value){let name=case["table"].as_str().unwrap();let operation=case["operation"].as_str().unwrap();if operation=="missing-table"{database.tables.retain(|table|table.name!=name);return}if operation=="extra-table"{database.tables.push(database.tables[0].clone());return}let table=database.tables.iter_mut().find(|table|table.name==name).unwrap();match operation{
 "cell"=>{let value=&case["value"];table.rows[case["row"].as_u64().unwrap()as usize].values[case["column"].as_u64().unwrap()as usize]=if value.is_null(){SqliteValue::Null}else if let Some(text)=value.as_str(){SqliteValue::Text(text.into())}else{SqliteValue::Integer(value.as_i64().unwrap())}},
 "duplicate-id"=>{table.rows[1].rowid=table.rows[0].rowid;table.rows[1].values[0]=table.rows[0].values[0].clone()},"id-mismatch"=>table.rows[0].values[0]=SqliteValue::Integer(999),"missing-row"=>{table.rows.pop();},"extra-row"=>{let mut row=table.rows[0].clone();row.rowid=999;row.values[0]=SqliteValue::Integer(999);table.rows.push(row)},"missing-column"=>{table.rows[0].values.pop();},"extra-column"=>table.rows[0].values.push(SqliteValue::Null),"orphan-parent"=>table.rows[0].values[1]=SqliteValue::Integer(999),"duplicate-ordinal"=>table.rows[1].values[2]=SqliteValue::Integer(0),"gapped-ordinal"=>table.rows[0].values[2]=SqliteValue::Integer(9),_=>panic!("closed validation edit")}}
macro_rules! run{
 ($function:ident,$native:ident,$recipient:path,$owner:ident,$method:ident,$progress:path,$cause:literal)=>{
 fn $function(source:&SpaceHistorySnapshot,database:&SqliteDatabase,grant:semio_framework_value::RetainedCloneGrant,mode:u8)->semio_framework_io_schema::IoResult<()>{
  let c=contract();let prior:semio_framework_value::RetainedCloneProgress=serde_json::from_value(c["priorProgress"].clone()).unwrap();let live=AtomicBool::new(true);let sql_live=AtomicBool::new(true);let cut=AtomicBool::new(false);let target=source.checkpoints.first().map(|checkpoint|checkpoint.message.len()).unwrap_or(0);let mut native_observer=|_|live.load(Ordering::Relaxed);let mut recipient=<$recipient>::new();let mut native=semio_framework_value::$native::new(c["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut native_observer);native.install_retirement_recipient(&mut recipient).unwrap();let mut owner=semio_framework_os_io::control::$owner::new(&mut native,grant);if mode!=3{owner.record_progress(prior).unwrap()}
  let mut progress=|event:SqliteSnapshotProgress|{if !sql_live.load(Ordering::Relaxed){return false}if mode>0&&mode<3&&target>=512&&event.total==target&&event.completed>=256{cut.store(true,Ordering::Relaxed);if mode==2{live.store(false,Ordering::Relaxed)}if mode==1{sql_live.store(false,Ordering::Relaxed)}return mode!=1}true};let limits=SqliteDatabaseLimits{max_allocation_bytes:c["sqlMaximumAllocationBytes"].as_u64().unwrap()as usize,..Default::default()};let mut control=SqliteSnapshotControl::new(&mut progress,limits);let original_cause=if mode==1{Some(control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,256,target).unwrap_err())}else if mode==2{live.store(false,Ordering::Relaxed);let error=owner.native().checkpoint().unwrap_err();live.store(true,Ordering::Relaxed);Some(error)}else{None};sql_live.store(true,Ordering::Relaxed);cut.store(false,Ordering::Relaxed);let coordinate=dialect();let before=control.allocation_remaining_bytes();let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||source.$method(&coordinate,database,&mut control,&mut owner));let received=owner.progress();drop(owner);assert_eq!(before-control.allocation_remaining_bytes(),native.owned_bytes(),"all received index/frame/cleanup births must reconcile through the same original SQL/native ledger");assert_eq!(received.retained_capacity_bytes,born);if mode!=3{assert!(received.copied_items>=prior.copied_items);assert!(received.copied_bytes>=prior.copied_bytes)}
  if mode==0{assert_eq!(born,released);assert!(!native.has_retirement_owner())}if mode==1||mode==2{assert!(cut.load(Ordering::Relaxed));assert_eq!(result.as_ref().unwrap_err().cause.kind,ValueRefusalKind::Canceled);assert_eq!(released,0);let expected=original_cause.as_ref().unwrap();let cause=&result.as_ref().unwrap_err().cause;assert_eq!(cause.message,expected.message);assert_eq!(cause.message.as_ptr(),expected.message.as_ptr());assert!(matches!(cause.message,std::borrow::Cow::Borrowed(_)));assert_eq!(cause.message,if mode==1{c["causes"]["sql"].as_str().unwrap()}else{$cause});assert!(born<target,"a borrowed validator must not allocate a temporary semantic text candidate")}
  if (mode==1||mode==2)&&native.has_retirement_owner(){let original_native=native.owned_bytes();let original_sql=control.allocation_remaining_bytes();let mut observe=|event:$progress|control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,event.completed,event.total).is_ok();let(refused,b,r)=semio_framework_trace_memory_testing::observe_backing(||native.scoped_observer(&mut observe,|native|native.close_retirement_recipient(caller_grant())));assert_eq!(refused.unwrap_err().kind,ValueRefusalKind::Canceled);assert_eq!((b,r),(0,0));assert!(native.has_retirement_owner());assert_eq!(native.owned_bytes(),original_native);assert_eq!(control.allocation_remaining_bytes(),original_sql);}
  live.store(true,Ordering::Relaxed);sql_live.store(true,Ordering::Relaxed);if native.has_retirement_owner(){let(zero,b,r)=semio_framework_trace_memory_testing::observe_backing(||native.close_retirement_recipient(Default::default()).unwrap());assert_eq!((zero.progress(),b,r),(Default::default(),0,0));let mut births=born;let mut releases=released;for _ in 0..c["maximumCloseTurns"].as_u64().unwrap(){if !native.has_retirement_owner(){break}let(step,b,r)=semio_framework_trace_memory_testing::observe_backing(||native.close_retirement_recipient(caller_grant()).unwrap());assert_eq!((b,r),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=b;releases+=r;}assert!(!native.has_retirement_owner());assert_eq!(births,releases)}result
 }
 };
}
