#[test]
fn sqlite_snapshot_framework_space_history_borrowed_validation_all_fields_signed_surrogates_and_malformed_cases(){
 let source=fixture();let unchanged=source.clone();let baseline=database();for exercise in [decode,encode]{exercise(&source,&baseline,caller_grant(),0).unwrap();let mut nul_source=source.clone();let mut nul_data=baseline.clone();let input=contract()["trueNul"].clone();nul_source.checkpoints[0].message=input["value"].as_str().unwrap().into();nul_data.tables.iter_mut().find(|table|table.name==input["table"].as_str().unwrap()).unwrap().rows[0].values[5]=SqliteValue::Text(nul_source.checkpoints[0].message.clone());assert!(nul_source.checkpoints[0].message.contains('\0'));exercise(&nul_source,&nul_data,caller_grant(),0).unwrap();for offset in contract()["signedOffsets"].as_array().unwrap(){let shifted=oracle::renumber(&baseline,offset.as_i64().unwrap());exercise(&source,&shifted,caller_grant(),0).unwrap();}for case in contract()["edits"].as_array().unwrap(){let mut malformed=baseline.clone();if case["operation"]=="duplicate-id"&&malformed.tables.iter().find(|table|table.name==case["table"].as_str().unwrap()).unwrap().rows.len()==1{let table=malformed.tables.iter_mut().find(|table|table.name==case["table"].as_str().unwrap()).unwrap();table.rows.push(table.rows[0].clone());}edit(&mut malformed,case);let result=exercise(&source,&malformed,caller_grant(),0).unwrap_err();assert_eq!(result.cause.kind,ValueRefusalKind::InvalidValue,"{}",case["id"]);}}assert_eq!(source,unchanged);
}
#[test]
fn sqlite_snapshot_framework_space_history_borrowed_validation_original_sql_native_cancel_and_zero_funded_close(){
 let c=contract();let mut source=fixture();source.checkpoints[0].message="\0語same-prefix".repeat(8192);let mut data=database();data.tables.iter_mut().find(|table|table.name=="space_history_checkpoint").unwrap().rows[0].values[5]=SqliteValue::Text(source.checkpoints[0].message.clone());let unchanged=source.clone();for exercise in [decode,encode]{for mode in [1,2]{let error=exercise(&source,&data,caller_grant(),mode).unwrap_err();assert_eq!(error.cause.kind,ValueRefusalKind::Canceled);}for axis in 0..5{let mut denied=caller_grant();match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=0,2=>denied.maximum_capacity_bytes=0,3=>denied.maximum_release_bytes=0,4=>denied.maximum_depth=0,_=>unreachable!()}assert!(exercise(&source,&data,denied,3).is_err(),"original grant axis{axis} must not be reset");}}assert_eq!(source,unchanged);assert_eq!(c["textChunkBytes"],256);
}

macro_rules! prior{
 ($name:ident,$native:ident,$recipient:path,$owner:ident,$method:ident)=>{
 #[test]fn $name(){let c=contract();let source=fixture();let data=database();let mut observer=|_|true;let mut recipient=<$recipient>::new();let mut native=semio_framework_value::$native::new(c["nativeMaximumBytes"].as_u64().unwrap()as usize,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let mut owner=semio_framework_os_io::control::$owner::new(&mut native,caller_grant());let mut progress=|_|true;let mut control=SqliteSnapshotControl::new(&mut progress,SqliteDatabaseLimits{max_allocation_bytes:c["sqlMaximumAllocationBytes"].as_u64().unwrap()as usize,..Default::default()});
  let coordinate=dialect();let(result,first_born,first_released)=semio_framework_trace_memory_testing::observe_backing(||source.$method(&coordinate,&data,&mut control,&mut owner));result.unwrap();let first=owner.progress();let first_native=owner.native().owned_bytes();let first_remaining=control.allocation_remaining_bytes();assert!(first.retained_capacity_bytes>0);assert!(first.released_bytes>0);assert_eq!((first.retained_capacity_bytes,first.released_bytes),(first_born,first_released));let(result,born,released)=semio_framework_trace_memory_testing::observe_backing(||source.$method(&coordinate,&data,&mut control,&mut owner));result.unwrap();let total=owner.progress();assert_eq!(total.retained_capacity_bytes,first.retained_capacity_bytes+born);assert_eq!(total.released_bytes,first.released_bytes+released);assert!(total.copied_items>first.copied_items);assert!(total.copied_bytes>first.copied_bytes);assert_eq!(first_remaining-control.allocation_remaining_bytes(),owner.native().owned_bytes()-first_native);assert_eq!(born,released);for axis in 0..3{let mut wrong=dialect();match axis{0=>wrong.artifact_kind="wrong".into(),1=>wrong.standard="2".into(),2=>wrong.subset="wrong".into(),_=>unreachable!()}let error=source.$method(&wrong,&data,&mut control,&mut owner).unwrap_err();assert_eq!(error.cause.kind,ValueRefusalKind::InvalidValue);assert_eq!(error.cause.message,"space history does not own this SQLite coordinate");assert!(matches!(error.cause.message,std::borrow::Cow::Borrowed(_)));}drop(owner);assert!(!native.has_retirement_owner());}
 };
}
